from toollib import *
GUIDES=[
tool('autoruns','Shows every program that starts automatically on Windows, and lets you switch any of them off.',
 ['Autoruns, from Microsoft, lists everything Windows starts by itself: startup programs, services, scheduled tasks, browser add-ons and drivers. Untick an entry to stop it starting; nothing is deleted.'],
 ['A computer is slow to start.','Pop-ups or strange behaviour come back after every restart.','Finding what a piece of malware left behind.'],
 [S('Open Autoruns, click Yes, and Agree to the licence the first time.', see='Tabs along the top (Everything, Logon, Services, Scheduled Tasks...) and a long list. It takes a minute to fill in.'),
  S('Click Options, tick Hide Microsoft Entries and Hide Windows Entries.', tip='This hides Windows\' own items so only third-party ones are left.'),
  S('Click the Logon tab first, then Scheduled Tasks and Services.'),
  S('Look for: rows in pink (no publisher or unsigned) or yellow (the file is missing), names you do not recognise, and anything starting from a Temp or Downloads folder.', tip='Right-click a row and choose Search Online to see what it is. Options, Scan Options, Check VirusTotal.com marks entries known to be malicious.'),
  S('Untick the box beside an entry to stop it starting.', see='The row stays listed, unticked. Tick it again to undo.'),
  S('Restart the computer and check whether the problem has gone.')],
 results=['Yellow "File not found" rows are leftovers from uninstalled programs; safe to untick or delete (right-click, Delete).','A VirusTotal score such as 0/70 is clean; 5/70 or more is worth removing.'],
 care=['Do not untick drivers or services you do not understand, especially anything from Intel, AMD, NVIDIA, Realtek or your antivirus. Unticking is safer than deleting because it can be undone.'],
 time='15 minutes', level='Takes care', related=['procexp','malwarebytes','bcu']),

tool('procexp','A much more detailed Task Manager: which program is using the processor, memory or a file.',
 ['Process Explorer, from Microsoft, shows every running program in a tree (which program started which), with how much processor and memory each uses, who made it and, optionally, its VirusTotal score.'],
 ['The computer is slow and Task Manager does not make the cause clear.','A file "is in use by another program" and you need to know which.','Checking whether a running program is suspicious.'],
 [S('Open Process Explorer, click Yes and Agree the first time.', see='A coloured tree of programs with CPU, Private Bytes (memory), Description and Company Name columns.'),
  S('Click the CPU column heading to put the busiest program on top. Click it twice for largest first.'),
  S('Hover over a program to see its full path, or double-click it for details.'),
  S('To check for malware: Options, VirusTotal.com, Check VirusTotal.com, then Agree.', see='A new VirusTotal column, such as 0/72.'),
  S('To find what locks a file: press Ctrl F, type part of the file name and click Search.', see='The program holding it. Close that program normally.'),
  S('To stop a stuck program, right-click it and choose Kill Process.', warn='Unsaved work in that program is lost. Never kill system processes such as csrss, wininit, lsass or svchost.')],
 results=['Purple rows are packed (compressed) programs, sometimes a malware trick. Pink are services, blue are your own programs.','"System Idle Process" high is normal: it is unused time.'],
 time='10 minutes', level='Takes care', related=['autoruns','procmon','tcpview']),

tool('malwarebytes','Finds and removes malware, adware and unwanted programs.',
 ['Malwarebytes is a well-known malware scanner. The free version scans and cleans when you run it; it does not protect all the time after the 14-day trial ends.'],
 ['Pop-ups, a browser that goes to strange sites, new toolbars, or after a scam.','A second opinion after Microsoft Defender.'],
 [S('Open Malwarebytes. If it asks, choose Personal computer and skip the trial and account offers.', see='A dashboard with a Scan button.'),
  S('Click Scan.', see='Stages: checking for updates, memory, startup items, registry, file system. Usually 5 to 20 minutes.'),
  S('When it finishes, read the list of threats found.', see='Each item with its type: Malware, PUP (potentially unwanted program) or PUM (changed settings).'),
  S('Leave everything ticked unless you recognise a program the person wants (some PUPs are tools they chose). Click Quarantine.'),
  S('Restart if asked, then scan again until nothing is found.')],
 results=['Quarantined items are disabled but kept. Detection history, Quarantine lets you restore one if it was a mistake, or delete them all.','PUP.Optional items are usually bundled junk, not dangerous malware.'],
 trouble=['Malwarebytes will not open or is blocked: the malware is stopping it. Restart in Safe Mode with Networking (see "Windows Safe Mode and recovery") and run it there.'],
 time='20 to 40 minutes', related=['adwcleaner','autoruns','basics-safety']),

tool('adwcleaner','Removes adware, browser hijackers and pushy "optimiser" programs.',
 ['AdwCleaner is a small Malwarebytes tool aimed at adware: toolbars, changed home pages and search engines, and unwanted browser add-ons. It runs without installing anything else.'],
 ['The browser\'s home page or search engine keeps changing.','Ads appear where they should not.'],
 [S('Close all browsers. Open AdwCleaner and Agree to the terms.', see='A dashboard with Scan now.'),
  S('Click Scan now.', see='Usually under a minute. Then a list of findings grouped by type.'),
  S('Leave everything ticked unless it is a program the person wants, and click Quarantine.'),
  S('Click Continue at the warning: programs will be closed.', see='A request to restart the computer.'),
  S('Restart. After restarting, a log opens showing what was removed.')],
 results=['Items under Preinstalled software are things the computer maker added. Untick them if the person uses them.','Basic repair (under Settings) also resets browser policies and network settings; leave it at default unless the browser is still hijacked.'],
 time='10 minutes', related=['malwarebytes','autoruns']),

tool('hwinfo','A complete report of every hardware part, and live sensors for all of them.',
 ['HWiNFO identifies every part (exact processor, motherboard, memory modules, drives, graphics) and shows hundreds of live sensors, with minimum, maximum and average.'],
 ['Finding exact part numbers before buying memory or a drive.','Watching temperatures and power during a stress test.','Battery wear on a laptop.'],
 [S('Open HWiNFO64 and click Yes.', see='A small window with Sensors-only and Summary-only options.'),
  S('For parts, tick Summary-only and click Start.', see='One page: processor, motherboard, memory (size, speed, number of slots), graphics and drives.'),
  S('For temperatures, close it, open it again, tick Sensors-only and click Start.', see='A long list with Current, Minimum, Maximum and Average columns.'),
  S('Find CPU Package (or Tctl/Tdie on AMD), the GPU temperature and the drive temperatures. Leave it open during the test and read the Maximum column.'),
  S('The clock icon at the bottom resets the minimum and maximum.')],
 results=['Red values are outside safe limits.','Laptop battery: under Battery, "Wear Level" over 20% means the battery is worn.'],
 time='5 minutes', related=['lhm','cpuz','occt']),

tool('ncdu','Shows what is using disk space, in Terminal, largest first.',
 ['ncdu scans a folder and lists what is inside, biggest first. You move around with the arrow keys. Useful on a Mac or Linux when the drive is full.'],
 ['The drive is full and you do not know why.','Working on a computer with no desktop, over a remote connection.'],
 [S('Open Terminal and type: ncdu ~', see='"Scanning..." then a list of folders in your home folder with sizes and bars.', tip='To scan the whole drive on Linux: sudo ncdu -x /'),
  S('Use the up and down arrows to pick a folder and press Enter (or the right arrow) to look inside it. Left arrow goes back up.'),
  S('Press d to delete the highlighted item, and confirm.', warn='Deleted items do not go to the Trash. Only delete things you are sure about, inside your own folders.'),
  S('Press q to quit.')],
 results=['Folders like Library/Caches (Mac) and .cache (Linux) are safe to clear. Look hard at large files in Downloads, Movies and Documents.'],
 time='5 minutes', ui='cli', related=['grandperspective','windirstat','mac-tools']),

tool('ddrescue','Copies a failing drive onto a healthy one, getting the good parts first.',
 ['GNU ddrescue copies a whole drive block by block, skipping damaged areas at first and coming back to them later, and keeps a log so it can be stopped and resumed. The standard first step with a dying drive: copy it once, then recover files from the copy.'],
 ['A drive clicks, is very slow, or shows read errors, and its files matter.','Before using TestDisk or PhotoRec on a drive that might fail completely.'],
 [S('Connect the failing drive and a healthy drive at least as large.', warn='Everything on the healthy (destination) drive will be overwritten. Getting the source and destination the wrong way round destroys the files you are trying to save.'),
  S('Find both drives. Linux: sudo lsblk -o NAME,SIZE,MODEL   Mac: diskutil list', see='Each drive with its size and model, such as sdb 500G and sdc 1T (Linux) or disk2 and disk3 (Mac). Write down which is which.'),
  S('Unmount any volumes on them. Mac: diskutil unmountDisk /dev/disk2 (for each). Linux: they are not mounted if nothing opened them.'),
  S('First pass, fast, skipping bad areas. Linux: sudo ddrescue -n /dev/sdb /dev/sdc rescue.map   Mac: sudo ddrescue -n /dev/rdisk2 /dev/rdisk3 rescue.map', tip='First the failing drive, then the healthy one, then the log file name. The -f option may be needed to write to a whole drive: add -f before -n.', see='A live status: rescued, bad areas, read errors and the time remaining.'),
  S('Second pass, retrying bad areas three times: same command with -r3 instead of -n.'),
  S('When finished, run TestDisk, PhotoRec, or MendKit\'s "Copy from an old drive" on the healthy copy, never on the failing drive.')],
 results=['"pct rescued" near 100% is a near-complete copy. Bad areas show how much could not be read.','The rescue.map file lets you stop with Ctrl C and run the same command later to continue.'],
 care=['If a drive makes clicking or grinding noises, every hour running can make it worse. For irreplaceable files, a professional lab is the safest choice.'],
 time='Several hours', level='Needs care', ui='cli', need=['A healthy drive at least as large as the failing one'], related=['testdisk','mk-old-drive','smartmontools']),

tool('lm-sensors','Reads temperatures and fan speeds on Linux.',
 ['lm-sensors reads the motherboard and processor sensors on Linux with the sensors command.'],['A Linux computer is hot, loud or shuts itself off.'],
 [S('Open Terminal and run once: sudo sensors-detect --auto', see='It probes for sensor chips and says which to load.'),
  S('Type: sensors', see='Lines such as "Package id 0: +45.0°C (high = +100.0°C, crit = +100.0°C)" and fan speeds in RPM.'),
  S('To watch it change, type: watch -n 2 sensors, and press Ctrl C to stop.')],
 results=['Compare each value to its high and crit numbers. Near high under light use means poor cooling.'],
 time='5 minutes', ui='cli', related=['stress-ng','btop']),

tool('inxi','Prints a full, readable summary of a Linux computer\'s hardware and system.',
 ['inxi prints the processor, memory, graphics, drives, network, battery and system in a neat summary. The usual way to describe a Linux computer to a technician or forum.'],['Finding out exactly what a Linux computer has, or sharing it for help.'],
 [S('Open Terminal and type: inxi -Fxz', see='Sections: System, Machine, Battery, CPU, Graphics, Audio, Network, Drives, Partition, Sensors, Info.', tip='-z hides serial numbers and network addresses, so it is safe to share.'),
  S('To copy it, select the text and press Ctrl Shift C.')],
 time='2 minutes', ui='cli', related=['lshw','basics-version']),

tool('iperf3','Measures the real speed between two computers on your own network.',
 ['iperf3 measures how fast data moves between two computers on the network, without the internet involved. It shows whether slow transfers are the Wi-Fi or the internet.'],['Wi-Fi seems slow even though the internet speed test is fine.','Checking a new network cable, switch or access point.'],
 [S('Install iperf3 on both computers.'),
  S('On the first computer, type: iperf3 -s', see='"Server listening on 5201". Leave it running.'),
  S('Find the first computer\'s address (MendKit\'s Network check shows it, for example 192.168.1.20).'),
  S('On the second computer, type: iperf3 -c 192.168.1.20', see='Ten lines of results, then a summary with Bitrate in Mbits/sec.'),
  S('Stop the first computer\'s server with Ctrl C.')],
 results=['Cable on a gigabit network: 900 Mbits/sec or more. Good Wi-Fi in the same room: 200 to 800. Under 50 points to poor Wi-Fi signal, an old router or interference.'],
 time='5 minutes', ui='cli', related=['mtr','nmap']),

tool('timeshift','Takes snapshots of a Linux system so a bad update can be undone.',
 ['Timeshift saves snapshots of the Linux system files. If an update or change breaks something, you can roll back to a snapshot. It does not back up personal files by default.'],['Before a big update or risky change on Linux.','Setting up automatic daily snapshots.'],
 [S('Open Timeshift and type your password.', see='The first time, a setup wizard.'),
  S('Choose RSYNC (or BTRFS if the system uses it) and click Next. Choose the drive to keep snapshots on and click Next.'),
  S('Pick a schedule, for example Daily with 5 kept, and click Next, then Finish.'),
  S('Click Create to take a snapshot now.', see='A new snapshot in the list with the date.'),
  S('To roll back, select a snapshot and click Restore, then follow the steps. The computer restarts.')],
 trouble=['Linux will not start after an update: start from a Linux live USB, install and open Timeshift there, and restore from it.'],
 time='15 minutes', related=['mk-backup-erase']),

tool('gparted','Shows and changes the partitions on drives on Linux: resize, create, delete and format.',
 ['GParted is the standard partition editor. It shows each drive as a bar divided into partitions and can resize, move, create, delete and format them.'],['Formatting a USB stick or new drive.','Making room on a drive or using space left after cloning to a larger SSD.'],
 [S('Open GParted and type your password.', see='The first drive as a coloured bar, with a table of its partitions, sizes and file systems. The drive menu at the top right switches drives.'),
  S('Choose the drive from the top right list. Check its size twice.', warn='Changing the wrong drive destroys its data. Back up before resizing anything.'),
  S('Right-click a partition for actions: Resize/Move, Delete, Format to, New (in unallocated space).'),
  S('Nothing changes until you click the green tick (Apply All Operations). Read the list, then click Apply.')],
 care=['You cannot change the partition Linux is running from. Use GParted Live from the ISO Library for that.'],
 time='10 to 60 minutes', level='Needs care', related=['mk-iso','rufus']),

tool('htop','A live list of running programs with processor and memory use, in Terminal.',
 ['htop shows every running program with bars for each processor core and memory, updating every second.'],['A Mac or Linux computer is slow and you need to see what is busy.'],
 [S('Open Terminal and type: htop', see='Coloured bars at the top for each core and memory, then a list of programs.'),
  S('Press F6 (or > ) and choose PERCENT_CPU or PERCENT_MEM to sort by processor or memory.'),
  S('To stop a stuck program, move to it with the arrows, press F9, choose 15 SIGTERM and press Enter.', warn='Unsaved work in that program is lost.'),
  S('Press q to quit.')],
 results=['Load average numbers higher than the number of cores mean the computer is overloaded.','Swp (swap) filling up means it needs more memory.'],
 time='5 minutes', ui='cli', related=['btop','mk-dashboard']),

tool('topgrade','Updates everything on a Mac in one command: Homebrew, apps and more.',
 ['topgrade runs every updater it finds: Homebrew packages and apps, Mac App Store apps (with mas), and more.'],['Bringing a technician\'s or power user\'s Mac fully up to date.'],
 [S('Open Terminal and type: topgrade', see='Each updater runs in turn with a heading, then a summary.'),
  S('Type your password if asked, and answer y to questions.'),
  S('Read the summary at the end.')],
 results=['Each step shows OK, FAILED or SKIPPED. A FAILED step names the updater; run it on its own for details.'],
 time='10 to 30 minutes', ui='cli', related=['mk-updates']),

tool('rufus','Writes an ISO file to a USB stick so a computer can start from it.',
 ['Rufus writes a single ISO image (such as a Windows installer) to a USB stick, setting it up correctly for older or newer computers.'],['Making a Windows install stick.','When Ventoy will not start a particular image.'],
 [S('Plug in the USB stick.', warn='Everything on the stick will be erased.'),
  S('Open Rufus and click Yes.', see='Device (the stick), Boot selection, Partition scheme, and Start.'),
  S('Check that Device shows your USB stick and its size.'),
  S('Click SELECT and choose the ISO file.', see='Rufus fills in the rest. For Windows 11 the partition scheme is GPT.'),
  S('Click START. For a Windows ISO, a box offers options such as removing the Microsoft account requirement or the hardware check; tick what you want and click OK. Confirm the warning.', see='A green bar and "READY" when finished.'),
  S('Click CLOSE and eject the stick.')],
 trouble=['The computer will not start from the stick: try the other partition scheme (MBR for very old computers, GPT for anything from about 2013 on).'],
 time='10 to 20 minutes', level='Takes care', need=['A USB stick of 8 GB or more','An ISO file'], related=['ventoy','basics-boot','mk-iso']),

tool('everything','Finds any file on a Windows computer by name, instantly.',
 ['Everything indexes every file name on the drives in seconds, then finds files as you type. Much faster than Windows search.'],['A file was saved "somewhere" and cannot be found.','Finding all files of a type, such as every .pst mail file before a migration.'],
 [S('Open Everything.', see='A search box and a list of every file, filling in within a minute the first time.'),
  S('Type part of the file name.', see='Matches appear as you type, with their folder, size and date.', tip='Type *.pst to find every Outlook data file, or *.jpg to find every photo. Click Date Modified to sort by date.'),
  S('Double-click a result to open it, or right-click and choose Open Path to open its folder.')],
 time='2 minutes', related=['wiztree']),

tool('wiztree','Shows what is using space on a drive, very quickly.',
 ['WizTree does the same job as WinDirStat but reads the drive\'s index directly, so a full drive scans in seconds.'],['The drive is full and you need to know why, fast.'],
 [S('Open WizTree and click Yes.', see='A drive choice at the top left and a Scan button.'),
  S('Choose C: and click Scan.', see='A Tree View of folders, largest first, a coloured map, and a File View tab listing the biggest files.'),
  S('Click File View to see the largest single files.'),
  S('Right-click to open a folder or delete.', warn='Do not delete anything in Windows, Program Files or ProgramData. Uninstall programs the normal way.')],
 time='5 minutes', related=['windirstat','treesize']),

tool('cpuz','Shows exactly which processor, motherboard and memory a PC has.',
 ['CPU-Z identifies the processor, motherboard, memory and graphics, and shows the memory slots used and their speed.'],['Checking what memory to buy, and whether a slot is free.','Confirming a processor runs at its expected speed.'],
 [S('Open CPU-Z and click Yes.', see='Tabs: CPU, Caches, Mainboard, Memory, SPD, Graphics, Bench, About.'),
  S('CPU: the processor name and current speed.'),
  S('Memory: total size, type (DDR4, DDR5) and channels (Dual is best).'),
  S('SPD: choose each slot in the drop-down. Empty slots show nothing; filled ones show the module\'s size, maker and part number.'),
  S('Mainboard: the motherboard model and BIOS version.')],
 results=['Channel # "Single" with two slots free: adding a matching module will speed the computer up.'],
 time='5 minutes', related=['hwinfo','gpuz']),

tool('gpuz','Shows the graphics card\'s exact model, driver and temperatures.',
 ['GPU-Z identifies the graphics card or chip and its driver, and shows live clock speeds, temperature and load.'],['Checking which graphics driver is installed.','A game or video stutters, or the screen goes black under load.'],
 [S('Open GPU-Z and click Yes (or Not now to installing).', see='Graphics Card tab with the name, memory and Driver Version.'),
  S('Click the Sensors tab for live GPU temperature, load and fan speed.'),
  S('If there are two graphics chips (common in laptops), choose each one in the list at the bottom.')],
 results=['GPU over about 85 °C under load is hot. Clean the fans.'],
 time='5 minutes', related=['ddu','cpuz']),

tool('crystaldiskmark','Measures how fast a drive reads and writes.',
 ['CrystalDiskMark tests a drive\'s read and write speed. It tells you whether a drive is performing as it should, or whether a "slow computer" is a slow drive.'],['A computer feels slow and you suspect the drive.','Checking a new SSD or a USB stick.'],
 [S('Close other programs. Open CrystalDiskMark and click Yes.', see='Four rows of tests, All, and Read and Write columns.'),
  S('Choose the drive in the list at the top right. Leave 5 runs and 1GiB.'),
  S('Click All.', see='Each test runs for a minute or two. Numbers appear in MB/s.')],
 results=['First row (SEQ1M) read: a hard drive manages about 100 to 200 MB/s, a SATA SSD about 500, an NVMe SSD 1,500 to 7,000.','Bottom row (RND4K Q1T1) read: a hard drive about 0.5 to 1, an SSD 30 to 90. This row matters most for how fast the computer feels.','An SSD scoring like a hard drive is failing, nearly full, or running in a slow mode.'],
 care=['Do not run it repeatedly on a drive that is already failing.'],
 time='5 minutes', related=['crystaldiskinfo']),
]
